message.content:
{
  "description": "The creature is shown in right-facing profile standing on a pale ground. It has a broad, flat, pale pinkish-tan head with large dark eyes and a wide mouth, with multiple feathery pinkish-red gill stalks projecting from the neck immediately behind the head. The body is stout and low to the ground, with a strongly arched back completely covered in overlapping dark brown scales with lighter edges, continuing onto the top of the long thick tail that extends to the left out of the frame. The underside of the body, the neck, and the four thick limbs are bare, pale, wrinkled and fleshy, and each limb ends in a splayed foot with small dark claws. The overall skin of the head and limbs is smooth with visible folds at the joints and neck, and the scales have a ridged, keratinous texture.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flat and rounded at the snout, pale pinkish-beige with gray-brown mottled speckling on top, large round eyes with black pupils and light blue-gray irises, small paired nostrils at the tip of the snout, and a slightly upturned wide mouth",
      "where": "at the frontmost end of the body, facing to the right"
    },
    {
      "part": "gills",
      "looks_like": "feathery, pinkish-red external gill stalks with many fine lateral filaments giving a comb-like appearance, fleshy at the base and branching distally",
      "where": "clustered on both sides of the neck directly behind the head, projecting outward and slightly backward, about five to six stalks visible in total"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, columnar limbs with pale pinkish-tan wrinkled fleshy skin, with transverse skin folds and slightly darker shading at the joints",
      "where": "two forelimbs under the chest and two hindlimbs under the mid-body, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "fleshy paws with five short toes each, tipped with small dark curved claws, the skin is pale and wrinkled with visible toe pads",
      "where": "at the distal ends of all four legs, splayed flat on the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick and tapering, dorsal surface covered in overlapping scales like the back, ventral and lateral surfaces pale, fleshy and wrinkled with transverse folds",
      "where": "extending to the left from the rear of the body, partially out of frame"
    },
    {
      "part": "scales",
      "looks_like": "large, overlapping, rounded keratinous scales in dark brown to gray-brown with lighter tan margins and fine radial ridges, arranged in diagonal overlapping rows",
      "where": "covering the entire dorsal surface from the back of the neck over the arched back and onto the dorsal side of the tail"
    },
    {
      "part": "markings",
      "looks_like": "mottled gray-brown speckling on the dorsal head, and pale transverse wrinkles and skin folds on the neck, underside of the torso, and limbs; the scales show tonal variation with darker centers",
      "where": "on the head, neck, ventral torso, and limbs, and within the scale covering itself"
    }
  ],
  "attached_objects": [],
  "animals": [
    "axolotl",
    "pangolin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
